<?php require __DIR__.'/oyunchu_config.php';
function mcset($k,$v){global $conn;$q=$conn->prepare("CREATE TABLE IF NOT EXISTS mc_prizes(level_no TINYINT UNSIGNED PRIMARY KEY,prize INT UNSIGNED NOT NULL,safe TINYINT(1) DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$q->execute();$q=$conn->prepare("INSERT INTO mc_prizes(level_no,prize,safe) VALUES(?,?,?) ON DUPLICATE KEY UPDATE prize=VALUES(prize),safe=VALUES(safe)");$q->bind_param('iii',$k,$v[0],$v[1]);$q->execute();}
$conn->query("CREATE TABLE IF NOT EXISTS mc_prizes(level_no TINYINT UNSIGNED PRIMARY KEY,prize INT UNSIGNED NOT NULL,safe TINYINT(1) DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$count=(int)$conn->query('SELECT COUNT(*) FROM mc_prizes')->fetch_row()[0];
if(!$count){$seed=[50,75,100,200,400,800,1500,3000,6000,12000,25000,50000];foreach($seed as $i=>$v)mcset($i+1,[$v,in_array($i+1,[5,10],true)?1:0]);}
$msg='';$time=(int)($_POST['time_limit']??30);if($_SERVER['REQUEST_METHOD']==='POST'){ga_verify();$time=max(10,(int)($_POST['time_limit']??30));$q=$conn->prepare("INSERT INTO es_settings(skey,svalue) VALUES('milyoncu_time_limit',?) ON DUPLICATE KEY UPDATE svalue=VALUES(svalue)");$q->bind_param('s',$time);$q->execute();for($i=1;$i<=12;$i++){ $pr=max(0,(int)($_POST['prize'][$i]??0));$safe=isset($_POST['safe'][$i])?1:0;mcset($i,[$pr,$safe]); }ga_audit('milyoncu_prizes','mc_prizes',null,'Milyonçu pillələri yeniləndi');$msg='Milyonçu pillələri yadda saxlanıldı.';}
$rows=$conn->query('SELECT * FROM mc_prizes ORDER BY level_no')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Milyonçu pillələri</title><script>document.documentElement.setAttribute('data-theme','dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php';?><main class="ga-main"><div class="ga-top"><b>💰 Milyonçu — pillə və mükafat idarəsi</b></div><div class="ga-content"><div class="ga-card"><p class="ga-muted">Artıq pillə mükafatları kodda hardcoded deyil. Buradan 12 sualın mükafatını və təhlükəsiz pillələri dəyişə bilərsiniz.</p><?php if($msg):?><div class="ga-alert"><?=ga_h($msg)?></div><?php endif;?><form method="post"><?=csrf_field()?><div style="margin-bottom:16px"><label class="ga-label">Sual üçün vaxt limiti (saniyə)</label><input class="ga-input" type="number" min="10" name="time_limit" value="<?=ga_h(gs_get('milyoncu_time_limit','30'))?>"></div><div class="ga-grid"><?php foreach($rows as $r):?><div class="ga-card"><h3><?=$r['level_no']?>. sual</h3><label class="ga-label">Mükafat (coin)</label><input class="ga-input" type="number" min="0" name="prize[<?=$r['level_no']?>]" value="<?=$r['prize']?>"><label style="display:block;margin-top:10px"><input type="checkbox" name="safe[<?=$r['level_no']?>]" <?=$r['safe']?'checked':''?>> 🔒 Təhlükəsiz pillə</label></div><?php endforeach;?></div><button class="ga-btn ga-primary">💾 Yadda saxla</button></form></div></div></main></body></html>